// P13/R29 任务：代码量统计与重复规则检查（纯只读，不运行构建/测试）。
//
// 测量口径：
//   扫描根：src、src-tauri（排除 target）、tests、tools、contracts、fixtures；
//   排除：node_modules、target、.artifacts、dist、二进制/资源类扩展名。
//   分类优先级（一个文件只归一类）：
//     1) generated：文件前 5 行含 "generated by"（大小写不敏感；ts-rs 生成头）；
//     2) tests：tests/ 目录下全部代码文件；
//     3) tools：tools/ 目录下脚本（含本脚本，统计时如实计入）；
//     4) 按扩展名归类：.ts/.tsx → 手写 TS/TSX；.rs → 手写 Rust；.typ → Typst；
//        .sql → SQL；.css → CSS。
//   行数取非空行（trim 后非空）。Rust 内联 #[cfg(test)] 不拆分，计入手写 Rust（见 notes）。
// 重复规则检查：
//   对每个文件做规范化（trim + 折叠连续空白；跳过空行）后取 30 行滑动窗口做哈希；
//   同一文件内连续相同哈希的窗口合并为一个实例（避免滑窗重叠把同一块拆成多条）；
//   按 hash 聚合实例，实例数 ≥2（跨文件或同文件两处）视为重复块；
//   块长度 = 30 + 该实例内最大滑动距离。列出 top10（按块长度、实例数排序）。
// 输出：
//   .artifacts/remaining/R29/session4-code-metrics.json
//   .artifacts/remaining/R29/session4-code-metrics.md
// 运行命令：node tools/bench/code-metrics.mjs
import { createHash } from "node:crypto";
import { readFile, readdir, stat, writeFile, mkdir } from "node:fs/promises";
import { join, resolve, extname, relative, sep } from "node:path";

const root = resolve(import.meta.dirname, "../..");
const outputRoot = join(root, ".artifacts", "remaining", "R29");
const scanRoots = ["src", "src-tauri", "tests", "tools", "contracts", "fixtures"];
const skipDirs = new Set(["node_modules", "target", ".artifacts", "dist", ".git"]);
const codeExtensions = new Set([".ts", ".tsx", ".rs", ".typ", ".sql", ".css", ".mjs", ".cjs", ".ps1", ".js"]);
const windowLines = 30;

async function* walk(directory) {
  let entries;
  try {
    entries = await readdir(directory, { withFileTypes: true });
  } catch {
    return;
  }
  for (const entry of entries) {
    if (entry.isDirectory()) {
      if (skipDirs.has(entry.name)) continue;
      yield* walk(join(directory, entry.name));
    } else if (entry.isFile()) {
      yield join(directory, entry.name);
    }
  }
}

function categoryFor(relativePath, header) {
  const normalized = relativePath.replaceAll(sep, "/");
  if (header && header.toLowerCase().includes("generated by")) return "generated";
  if (normalized.startsWith("tests/")) return "tests";
  if (normalized.startsWith("tools/")) return "tools";
  const extension = extname(relativePath);
  if (extension === ".ts" || extension === ".tsx") return "handwrittenTs";
  if (extension === ".rs") return "handwrittenRust";
  if (extension === ".typ") return "typst";
  if (extension === ".sql") return "sql";
  if (extension === ".css") return "css";
  if (extension === ".mjs" || extension === ".js" || extension === ".cjs" || extension === ".mts") {
    return "handwrittenJs"; // src/、src-tauri/ 下随产品交付的手写 JS（如 src/ui/services/version-schema.mjs）
  }
  return null; // 其余扩展名（.json/.ps1 等）不计
}

function normalizeLine(line) {
  return line.trim().replace(/\s+/g, " ");
}

async function main() {
  const files = [];
  const skippedFiles = [];
  for (const scanRoot of scanRoots) {
    for await (const filePath of walk(join(root, scanRoot))) {
      const extension = extname(filePath);
      if (!codeExtensions.has(extension)) {
        skippedFiles.push(relative(root, filePath));
        continue;
      }
      files.push(filePath);
    }
  }
  files.sort();

  const categories = {
    handwrittenTs: { label: "手写 TS/TSX（src，src-tauri 侧生成文件除外）", fileCount: 0, nonEmptyLines: 0 },
    handwrittenRust: { label: "手写 Rust（src-tauri，含内联测试）", fileCount: 0, nonEmptyLines: 0 },
    typst: { label: "Typst（引擎模板）", fileCount: 0, nonEmptyLines: 0 },
    sql: { label: "SQL（独立 .sql 文件）", fileCount: 0, nonEmptyLines: 0 },
    css: { label: "CSS", fileCount: 0, nonEmptyLines: 0 },
    handwrittenJs: { label: "手写 JS（src/src-tauri 下非测试/工具的 .mjs/.js）", fileCount: 0, nonEmptyLines: 0 },
    tests: { label: "测试（tests/ 下 .mjs/.ps1 等）", fileCount: 0, nonEmptyLines: 0 },
    tools: { label: "工具脚本（tools/ 下，含基准脚本与本脚本）", fileCount: 0, nonEmptyLines: 0 },
    generated: { label: "生成代码（文件头含 generated by）", fileCount: 0, nonEmptyLines: 0 },
  };
  const generatedByDir = {};
  const windowHashMap = new Map(); // hash -> [{ file, normIdx, origStart }]
  let scannedCount = 0;

  for (const filePath of files) {
    const relativePath = relative(root, filePath);
    const content = await readFile(filePath, "utf8");
    const rawLines = content.split(/\r?\n/);
    const header = rawLines.slice(0, 5).join("\n");
    const category = categoryFor(relativePath, header);
    if (!category) {
      skippedFiles.push(relativePath);
      continue;
    }
    const nonEmpty = rawLines.filter((line) => line.trim() !== "").length;
    categories[category].fileCount += 1;
    categories[category].nonEmptyLines += nonEmpty;
    if (category === "generated") {
      const dir = relativePath.split(sep).slice(0, -1).join("/");
      generatedByDir[dir] = generatedByDir[dir] ?? { fileCount: 0, nonEmptyLines: 0 };
      generatedByDir[dir].fileCount += 1;
      generatedByDir[dir].nonEmptyLines += nonEmpty;
    }

    // 30 行滑动窗口重复检测：规范化后建窗口哈希，记录（文件，规范化下标，原起始行）。
    const normalized = [];
    const normToOrig = [];
    rawLines.forEach((line, index) => {
      const normalizedLine = normalizeLine(line);
      if (normalizedLine !== "") {
        normalized.push(normalizedLine);
        normToOrig.push(index + 1);
      }
    });
    if (normalized.length >= windowLines) {
      for (let start = 0; start + windowLines <= normalized.length; start += 1) {
        const slice = normalized.slice(start, start + windowLines);
        const hash = createHash("sha1").update(slice.join("\n")).digest("hex");
        const record = windowHashMap.get(hash);
        const occurrence = { file: relativePath, normIdx: start, origStart: normToOrig[start] };
        if (record) record.push(occurrence);
        else windowHashMap.set(hash, [occurrence]);
      }
    }
    scannedCount += 1;
  }

  // 聚合成"重复区域"：同一 hash 的出现位置两两组成实例对（fileA, i1)↔(fileB, i2)；
  // 同一文件对、同一位移差（delta=i2-i1）且 i1 连续的对合并为对角线链，
  // 链长 = 30 + 滑动距离，即该重复区域的最大行数。输出按块行数排序的 top10。
  const pairMap = new Map(); // "a\0b\0delta" -> [{ i1, origA, origB }]
  for (const occurrences of windowHashMap.values()) {
    if (occurrences.length < 2) continue;
    const sorted = [...occurrences].sort((left, right) =>
      left.file.localeCompare(right.file) || left.normIdx - right.normIdx);
    for (let i = 0; i < sorted.length; i += 1) {
      for (let j = i + 1; j < sorted.length; j += 1) {
        const a = sorted[i];
        const b = sorted[j];
        if (a.file === b.file && a.normIdx === b.normIdx) continue;
        const key = `${a.file}\u0000${b.file}\u0000${b.normIdx - a.normIdx}`;
        const list = pairMap.get(key);
        const pair = { i1: a.normIdx, origA: a.origStart, origB: b.origStart };
        if (list) list.push(pair);
        else pairMap.set(key, [pair]);
      }
    }
  }
  const regions = [];
  for (const [key, pairs] of pairMap) {
    const [fileA, fileB, deltaText] = key.split("\u0000");
    pairs.sort((left, right) => left.i1 - right.i1);
    let start = pairs[0];
    let previousI1 = pairs[0].i1;
    const flush = (end) => regions.push({
      fileA,
      fileB,
      delta: Number(deltaText),
      blockLines: windowLines + (end.i1 - start.i1),
      startLineA: start.origA,
      startLineB: start.origB,
    });
    for (let index = 1; index < pairs.length; index += 1) {
      if (pairs[index].i1 === previousI1 + 1) {
        previousI1 = pairs[index].i1;
      } else {
        flush(pairs[index - 1]);
        start = pairs[index];
        previousI1 = pairs[index].i1;
      }
    }
    flush(pairs[pairs.length - 1]);
  }
  const duplicates = regions
    .sort((left, right) => right.blockLines - left.blockLines)
    .slice(0, 10);
  // 为 top10 补充首行预览（回读示例位置附近的原文）。
  const previewCache = new Map();
  for (const region of duplicates) {
    if (!previewCache.has(region.fileA)) {
      previewCache.set(region.fileA, (await readFile(join(root, region.fileA), "utf8")).split(/\r?\n/));
    }
    const lines = previewCache.get(region.fileA);
    const slice = lines.slice(region.startLineA - 1, region.startLineA - 1 + region.blockLines);
    const firstMeaningful = slice.find((line) => line.trim() !== "") ?? "";
    region.preview = firstMeaningful.trim().slice(0, 120);
  }

  const totalFiles = Object.values(categories).reduce((sum, item) => sum + item.fileCount, 0);
  const totalLines = Object.values(categories).reduce((sum, item) => sum + item.nonEmptyLines, 0);
  const handwrittenLines = categories.handwrittenTs.nonEmptyLines
    + categories.handwrittenJs.nonEmptyLines
    + categories.handwrittenRust.nonEmptyLines
    + categories.typst.nonEmptyLines
    + categories.sql.nonEmptyLines
    + categories.css.nonEmptyLines;
  const generated = categories.generated;

  const report = {
    schemaVersion: 1,
    capturedAt: new Date().toISOString(),
    scope: {
      roots: scanRoots,
      skippedDirectories: [...skipDirs],
      windowLines,
      normalization: "trim + collapse whitespace, empty lines dropped, per-file consecutive identical windows deduped",
    },
    categories: Object.fromEntries(Object.entries(categories).map(([key, value]) => [key, {
      label: value.label,
      fileCount: value.fileCount,
      nonEmptyLines: value.nonEmptyLines,
    }])),
    generatedByDir,
    totals: {
      files: totalFiles,
      nonEmptyLines: totalLines,
      handwrittenNonEmptyLines: handwrittenLines,
      generatedToHandwrittenRatio: handwrittenLines
        ? Math.round((generated.nonEmptyLines / handwrittenLines) * 1000) / 1000
        : null,
    },
    duplicates: {
      windowLines,
      normalization: "trim + collapse whitespace, empty lines dropped; occurrences of identical windows merged into maximal diagonal chains per file pair (delta = i2 - i1), chain length = block size",
      top: duplicates,
    },
    notes: [
      "Rust 内联 #[cfg(test)] 模块不拆分，计入手写 Rust；tests/ 目录为自动化测试脚本。",
      "src/ui/services/version-schema.mjs（及其 .d.mts 声明）为随产品交付的手写 JS，计入手写 JS 类别。",
      "SQL 目前无独立 .sql 文件，schema 以内嵌字符串存在于 src-tauri（storage/migrations.rs 等），因此 sql 类计数为 0 不代表无 SQL。",
      "tools/ 统计含本脚本与 P13 新增基准脚本（tools/bench/）。",
      "生成目录当前为 src-tauri/src/domain/bindings/（ts-rs 产物，.ts 文件）；src/domain/bindings/ 不存在。",
    ],
    skippedFiles: {
      count: skippedFiles.length,
      sample: skippedFiles.slice(0, 20),
    },
  };

  await mkdir(outputRoot, { recursive: true });
  const jsonPath = join(outputRoot, "session4-code-metrics.json");
  await writeFile(jsonPath, `${JSON.stringify(report, null, 2)}\n`, "utf8");

  const lines = [
    "# R29 / P13 代码量统计汇总（session4）",
    "",
    `生成时间：${report.capturedAt}；扫描根：${scanRoots.join("、")}（排除 node_modules/target/.artifacts/dist）。行数为非空行。`,
    "",
    "| 类别 | 文件数 | 非空行数 |",
    "| --- | ---: | ---: |",
    ...Object.entries(categories).map(([key, value]) => `| ${value.label} | ${value.fileCount} | ${value.nonEmptyLines} |`),
    `| **合计** | **${totalFiles}** | **${totalLines}** |`,
    "",
    `- 手写代码（TS/Rust/Typst/SQL/CSS）非空行：${handwrittenLines}`,
    `- 生成代码（ts-rs bindings）非空行：${generated.nonEmptyLines}（${generated.fileCount} 个文件，位于 ${Object.keys(generatedByDir).join("、") || "-"}）`,
    `- 生成/手写比：${report.totals.generatedToHandwrittenRatio ?? "-"}`,
    "",
    `## 重复块 top${duplicates.length}（≥${windowLines} 行规范化窗口聚合，实例 ≥2 处）`,
    "",
    "| 排名 | 块行数 | 位置 A | 位置 B | 首行预览 |",
    "| --- | ---: | --- | --- | --- |",
    ...duplicates.map((record, index) => `| ${index + 1} | ${record.blockLines} | ${record.fileA}:${record.startLineA} | ${record.fileB}:${record.startLineB} | ${record.preview.replace(/\|/g, "\\|")} |`),
    "",
    "## 说明",
    "",
    ...report.notes.map((note) => `- ${note}`),
    "",
    `详细数据：${relative(outputRoot, jsonPath).replaceAll(sep, "/")}（本目录 session4-code-metrics.json）。`,
    "",
  ];
  const mdPath = join(outputRoot, "session4-code-metrics.md");
  await writeFile(mdPath, lines.join("\n"), "utf8");

  const info = await stat(jsonPath);
  console.log(JSON.stringify({
    jsonPath,
    mdPath,
    categories: report.categories,
    totals: report.totals,
    duplicateTopCount: duplicates.length,
    scannedFiles: scannedCount,
    jsonBytes: info.size,
  }, null, 2));
}

await main();
